-- DBeaver Seed Data for HRM (Oracle Database) - 500 Employees, 28 Projects, 140 Tasks
-- Chú ý: Cần bấm Alt + X (Execute Script) để chạy toàn bộ file.

-- 1. Xóa dữ liệu cũ và reset sequence
DELETE FROM tasks;
DELETE FROM projects;
DELETE FROM user_accounts;
DELETE FROM employees;

-- Reset identity column (Oracle 12c+)
ALTER TABLE tasks MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH 1);
ALTER TABLE projects MODIFY id GENERATED BY DEFAULT AS IDENTITY (START WITH 1);

